app.post('/vog', async (req, res) => {
    try {
        // Check if the username already exists in the database
        const existingUserByUsername = await cartModel.findOne({ uname: req.body.username });
        
        // Check if the name already exists in the database
        const existingUserByName = await cartModel.findOne({ name: req.body.name });

        if (existingUserByUsername&&existingUserByName) {
            // If the username already exists, return an error message
            return res.json({ message: 'Username already exists' });
        }
        else {
            // If both username and name do not exist, create a new entry in the database
            const newUser = await cartModel.create(req.body);
            return res.json(newUser);
        }
    } catch (err) {
        // Catch and return any error that occurs
        return res.json({ error: err.message });
    }
});


