app.get('/addcart/:username', async (req, res) => {
    const { username } = req.params; // Extract username from the URL parameters

    try {
        const carts = await cartModel.find({ uname: username });

        if (carts.length > 0) {
            res.json(carts);
        } else {
            res.status(404).json({ message: 'No carts found for this user' });
        }
    } catch (err) {
        console.error('Error fetching carts:', err);
        res.status(500).json({ message: 'Error fetching carts', error: err });
    }
});


